import logging
import os
import re
import time
from datetime import datetime

from ta_ue_plugin_android.uepc.adb_cmd_runners import AdbCmdRunner
# ignore_test_imports_magic_string
from ta_ue_plugin_android.uepc.qmdl_decoder import QmdlDecoder
from ta_ue_plugin_android.uepc.ue_control_utils import UeControlUtils
from ta_ue_plugin_android.uepc.ue_manager_exceptions import DiagCfgFileNotFoundError, \
    DiagMdlogStillRunningError, DiagMdlogNotRunningError, QmdlFileTransferToUePcError, FileWasNotFoundError, \
    DirectoryNotFoundError, QmdlNotFoundOnAndroidError, QmdlNotFoundOnUePcError, DecodedQmdlFileError
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class DiagUeRunner(object):
    """
    Module responsible for collecting rrc messages from android ue.
    Rooted android UE is required.
    """
    # pylint: disable=too-many-instance-attributes
    CMD_FOR_ROOT_CHECK = 'su'
    DIAG_CFG_PATH = '/sdcard/diag_logs/DIAG.cfg'
    LOGS_ROOT_PATH = '/sdcard/diag_logs'
    UES_WITH_MODIFIED_CMD = ['Unknown Android on blue_cdb']
    UES_WITH_ADB_CMD_RUNNER = ['Xiaomi Mi MIX 2S']

    def __init__(self, ue_control):
        """
        Basic initialization.
        :param ue_control:
        """
        self.ue_control = ue_control
        self.ue_model = self.ue_control.get_cached_ue_model()
        self.ue_control_utils = UeControlUtils(self.ue_control)
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'RRC_MSGS'})
        self.out = None
        self.adb_runner = AdbCmdRunner()
        self.decoded_and_analyzed_filepath = None
        self.qmdl_file_path = None
        self.dir_logs_path = None
        self.diag_cfg_win_path = None
        self.qcat_exe_path = None
        self.qmdl_size = None
        self.ue_root_cmd = ''

    def _check_if_ue_should_use_adb_to_run_root_cmds(self):
        out = self._run_cmd_on_ue_and_return_output_lines('{} echo test'.format(self.ue_root_cmd))
        if any('inaccessible or not found' in line for line in out):
            self.logger.debug('Root not available to app - all subsequent su calls will be made via adb shell.')
            self.UES_WITH_ADB_CMD_RUNNER.append(self.ue_model)

    def start_rrc(self, qcat_exe_path, diag_cfg_path, qmdl_size):
        """Start diag_mdlog on Android UE - start collecting qmdl file with rrc messages from qualcomm chipset."""
        self.logger.info('Starting rrc logging on UE.')
        self.diag_cfg_win_path = diag_cfg_path
        self.qcat_exe_path = qcat_exe_path
        self.qmdl_size = qmdl_size
        self.ue_root_cmd = self.get_ue_su_prefix()
        self._check_if_ue_should_use_adb_to_run_root_cmds()
        self.logger.debug('Ensuring that DIAG.cfg file exists on UE.')
        try:
            self.ensure_diag_cfg_exists()
            self.copy_diag_cfg_to_ue()
        except DiagCfgFileNotFoundError:
            self.logger.debug('DIAG.cfg file not found on UE! Copying it from UE PC {}.'.format(diag_cfg_path))
            self.copy_diag_cfg_to_ue()
        self._make_dir_for_diag_logs()
        self.ensure_diag_mdlog_proc_is_ended()
        self.logger.debug('Starting diag_mdlog process on UE..')
        self._other_preparations_before_run_diag_mdlog()
        self.run_diag_mdlog_cmd()
        self._wait_for_diag_mdlog_is_running()

    def _wait_for_diag_mdlog_is_running(self, timeout=5):
        self.logger.debug('Ensuring that diag_mdlog process is started on UE.')
        end_time = time.time() + timeout
        while self._is_diag_mdlog_running() is False:
            if time.time() > end_time:
                raise DiagMdlogNotRunningError('Can not start diag_mdlog application on UE!')
            time.sleep(1)

    def _is_diag_mdlog_running(self):
        _out, _err = self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['shell'] + '{} \"ps\"'.format(self.ue_root_cmd).split(' '))
        self.logger.debug("Got result from adb shell, out: '{}', err: '{}'".format(_out, _err))
        if 'diag_mdlog' in _out:
            self.logger.debug('diag_mdlog process found!')
            return True
        self.logger.debug('diag_mdlog process not found!')
        return False

    def run_diag_mdlog_cmd(self):
        """Start diag_mdlog application on Android UE."""
        diag_mdlog_cmd = self._create_cmd_to_run_diag()
        self.out = self._run_cmd_ue_specific(diag_mdlog_cmd)
        self.logger.debug(
            'Diag_mdlog should be running now. Command used = {}, output = {}'.format(diag_mdlog_cmd, self.out))

    def _run_cmd_ue_specific(self, diag_mdlog_cmd):
        self.logger.debug('Running diag_mdlog with adb shell.')
        out = self._run_cmd_in_adb_shell(diag_mdlog_cmd)
        return out

    def _run_cmd_in_adb_shell(self, cmd, get_output=False):
        return self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['shell'] + cmd.split(' '),
                                                   wait_for=get_output)

    def _run_cmd_on_ue_and_get_non_blocking_output(self, diag_mdlog_cmd):
        return self.ue_control.ueman.run_cmd_and_get_non_blocking_output(diag_mdlog_cmd)

    def _create_cmd_to_run_diag(self):
        cmd_opt = ''
        if bool(self.qmdl_size):
            cmd_opt = '-s {} -o {}'.format(self.qmdl_size, self.dir_logs_path)
        else:
            cmd_opt = '-o {}'.format(self.dir_logs_path)
        if self.ue_model in self.UES_WITH_MODIFIED_CMD:
            cmd = 'echo $$; {} \"diag_mdlog -m /sdcard/diag_logs/DIAG.cfg {} > {}/diag_out.txt\"'.format(
                self.ue_root_cmd, cmd_opt, self.LOGS_ROOT_PATH)
        else:
            cmd = 'echo $$; {} diag_mdlog -m /sdcard/diag_logs/DIAG.cfg {} > {}/diag_out.txt'.format(
                self.ue_root_cmd, cmd_opt, self.LOGS_ROOT_PATH)
        return cmd

    def _diag_process_name(self):
        return 'diag_mdlog'

    def _create_cmd_to_run_diag_kill(self):
        if self.ue_model in self.UES_WITH_MODIFIED_CMD:
            return '{} \"diag_mdlog -k\"'.format(self.ue_root_cmd)
        return '{} diag_mdlog -k'.format(self.ue_root_cmd)

    def stop_rrc(self, windows_logs_dir, qcat_analyzer=None, rrc_filter_file_path=None, mdm=None, use_decoding=None):
        """
        Stop diag_mdlog application on Android UE, convert qmdl to .txt and return path to txt file on UE PC
        :param windows_logs_dir: Logs directory on windows where qmdl file should be copied
        :param qcat_exe_path: path to QCAT exe on Windows UE PC
        :param diag_cfg_path: path to DIAG.cfg file on Windows UE PC (required to run diag_mdlog application on Android UE)
        :param rrc_filter_file_path: path to rrc_filter file
        :param mdm: use or not mdm directory
        :param use_decoding: use decoding or not
        :return:
        """
        self.logger.info('Stopping rrc logging on UE.')
        if self.out:
            self.out.close()
        self.ensure_diag_mdlog_proc_is_ended()
        # string_to_check = 'creating new file ' + self.dir_logs_path
        string_to_check = 'mask file name is:'
        self.logger.debug('=============================')
        self.logger.debug('Checking if string "{}" occured in diag_mdlog output'.format(string_to_check))
        cat_txt = self._run_cmd_on_ue_and_return_output_lines('cat {}/diag_out.txt'.format(self.LOGS_ROOT_PATH))
        self.logger.debug('diag_mdlog output = {}'.format(cat_txt))
        result = self._check_lst_strings(cat_txt, string_to_check)
        if not result:
            # do not throw an Exception - on some UEs diag_mdlog does not show any output, also when output is redirected to a file
            # raise DiagMdlogVerificationStringError('diag_mdlog does not have string {}! diag_mdlog output = {}'.format(string_to_check, cat_txt))
            self.logger.debug(
                'diag_mdlog does not have string {}! diag_mdlog output = {}'.format(string_to_check, cat_txt))
        if use_decoding:
            self.decoded_and_analyzed_filepath = self._decode_qmdl(windows_logs_dir, qcat_analyzer,
                                                                   rrc_filter_file_path, mdm)
            self.logger.info(
                'RRC logging stopped on UE. Txt file with logs = {}'.format(self.decoded_and_analyzed_filepath))
        else:
            self.qmdl_file_path, ue_file_name = self.transfer_qmdl_from_ue_to_pc(windows_logs_dir, mdm)
            self.logger.debug('Qmdl file transfered to uepc path {}'.format(self.qmdl_file_path))
            self.logger.info('RRC logging stopped on UE. '
                             'Decoding has been not triggered due to use_decoding parameter = {}.'.format(use_decoding))

    def get_decoded_and_anaylzed_filepaths(self):
        """
        Returns result of rrc with decoding.
        :return: (decoded_filepath, analyzed_filepaths) or None
        """
        return self.decoded_and_analyzed_filepath

    def get_qmdl_file_path(self):
        """
        Returns result of rrc without decoding.
        :return: raw qmdl_filepath or None
        """
        return self.qmdl_file_path

    def _check_lst_strings(self, lst, string_to_find):
        for string in lst:
            if string_to_find in string:
                return True
        return False

    def kill_proc_on_ue(self, proc_name):
        """
        Method used to kill process on Android UE
        :param proc_name: process name to terminate
        """
        cmd = 'ps | grep {}'.format(proc_name)
        out = self._run_cmd_on_ue_and_return_output_lines(cmd)
        self.logger.debug(out)
        for element in out:
            ps_lst = element.split()
            pid = ps_lst[1]
            self.kill_by_pid(pid)
        time.sleep(6)

    def kill_by_pid(self, pid):
        """
        Method used to kill specific PID on Android UE
        :param pid: Android PID
        """
        cmd = 'kill {}'.format(pid)
        self.logger.debug(cmd)
        self._run_cmd_on_ue_and_return_output_lines(cmd)

    def ensure_diag_mdlog_proc_is_ended(self):
        """
        Method checking if diag_mdlog application was properly terminated on Android UE
        :return: return True when diag_mdlog not running or raise exception
        """
        self.logger.debug('Ensuring that diag_mdlog process is ended on UE.')
        self._diag_mdlog_kill()
        if not self.check_if_proc_is_killed(self._diag_process_name()):
            self.logger.debug('Killing diag_mdlog process.')
            self.kill_proc_on_ue(self._diag_process_name())
            if not self.check_if_proc_is_killed(self._diag_process_name()):
                raise DiagMdlogStillRunningError('diag_mdlog proces is still running!')
        self.logger.debug('diag_mdlog process is not running on UE.')
        return True

    def _diag_mdlog_kill(self):
        cmd = self._create_cmd_to_run_diag_kill()
        return self._run_cmd_ue_specific(cmd)

    def check_if_proc_is_killed(self, proc_name, timeout=5):
        """
        Checks if given process name is not running on Android UE
        :param proc_name: Android UE process name
        :param timeout: Timeout waiting for correct answer
        :return: True of False
        """
        start_time = time.time()
        result = False
        while time.time() - start_time < timeout and not result:
            result = self._run_cmd_on_ue_and_expect_something_in_output('ps', proc_name)
            self.logger.debug("Checking if process {} is killed, result={}".format(proc_name, result))
        return result

    def ensure_diag_mdlog_proc_is_running(self):
        """
        Checks is diag_mdlog process is running on Android UE
        :return:
        """
        result = self._run_cmd_on_ue_and_expect_something_in_output('ps', self._diag_process_name())
        if result:
            raise DiagMdlogNotRunningError('diag_mdlog proces is not running!')
        return result

    def get_ue_su_prefix(self):
        """Check if Android UE is rooted, raises exception when UE is not rooted."""
        return self.ue_control_utils.get_su_prefix()

    def verify_diag_mdlog_output(self, diag_out):
        """
        Checks diag_mdlog application output
        :param diag_out: diag_mdlog application output
        :return: True of False
        """
        return bool('creating new file' in diag_out)

    def _make_dir_for_diag_logs(self):
        self.dir_logs_path = self._get_dir_for_diag_logs()
        cmd = 'cd ' + self.LOGS_ROOT_PATH + '; mkdir ' + self.dir_logs_path
        self.logger.debug('Creating tmp directory for diag logs using command: {}'.format(cmd))
        if self.ue_model not in self.UES_WITH_MODIFIED_CMD:
            out = self._run_cmd_on_ue_and_get_non_blocking_output(cmd)
            self.logger.debug('Output = {}'.format(out))

    def _get_dir_for_diag_logs(self):
        directory = self.LOGS_ROOT_PATH + '/' + self._get_current_date_time()
        return directory

    def _get_current_date_time(self):
        date_time = str(datetime.now().strftime('%Y%m%d_%H%M%S'))
        return date_time

    def _run_cmd_on_ue_and_expect_something_in_output(self, cmd, expected_output):
        out = self._run_cmd_on_ue_and_get_non_blocking_output(cmd)
        return self._expect_txt_in_non_blocking_output(out, expected_output)

    def _run_cmd_on_ue_and_return_output_lines(self, cmd):
        non_blocking_output = self._run_cmd_on_ue_and_get_non_blocking_output(cmd)
        output_in_lines = self._non_blocking_output_to_lines(non_blocking_output)
        self.logger.debug('cmd: {} sent to UE, output: {}'.format(cmd, output_in_lines))
        return output_in_lines

    def _expect_txt_in_non_blocking_output(self, out, txt, timeout=30):
        result = []
        end_time = time.time() + timeout
        self.logger.debug(end_time)
        while not out.is_finish() and time.time() <= end_time:
            self.logger.debug('Waiting for android cmd to end, time: {}'.format(time.time()))
            if not out.has_line_without_blocking():
                time.sleep(1)
                continue
            lines = out.read_lines()
            self.logger.debug('Output from android: {}'.format(lines))
            result += lines
            for line in lines:
                if txt in line:
                    return False
        return True

    def _non_blocking_output_to_lines(self, non_blocking_output):
        result = []
        while not non_blocking_output.is_finish():
            if not non_blocking_output.has_line_without_blocking():
                time.sleep(0.01)
                continue
            lines = non_blocking_output.read_lines()
            result += lines
        return result

    def _check_if_ue_is_rooted(self, out):
        return self._expect_txt_in_non_blocking_output(out, 'su: not found', 3)

    def return_diag_logs_path(self):
        """
        Returns path to diag logs directory on Android UE
        :return: path to diag logs directory on Android UE
        """
        return self.dir_logs_path

    def ensure_diag_cfg_exists(self):
        """Ensure that DIAG.cfg file exists on Android UE."""
        self.ensure_logs_root_andr_exists()
        if not self.check_if_diag_cfg_exists():
            raise DiagCfgFileNotFoundError()

    def check_if_diag_cfg_exists(self):
        """Checks if DIAG.cfg exists."""
        cmd = 'ls ' + self.LOGS_ROOT_PATH
        return not self._run_cmd_on_ue_and_expect_something_in_output(cmd, 'DIAG.cfg')

    def ensure_logs_root_andr_exists(self):
        """Ensures that Android logs directory exists."""
        cmd = 'ls ' + self.LOGS_ROOT_PATH
        cmd_mkdir = 'mkdir ' + self.LOGS_ROOT_PATH
        if not self._run_cmd_on_ue_and_expect_something_in_output(cmd, 'No such file or directory'):
            self.logger.debug('Running cmd: {}'.format(cmd_mkdir))
            self._run_cmd_on_ue_and_return_output_lines(cmd_mkdir)

    def adb_push_file(self, file_local_path, file_ue_path):
        """
        Push file to Android UE via ADB
        :param file_local_path: path to local file on UE PC
        :param file_ue_path: target path on Android UE
        """
        self.ue_control.adb_push_file(file_local_path, file_ue_path)

    def adb_pull_file(self, file_local_path, file_ue_path):
        """
        Pull file from Android UE to UE PC via ADB
        :param file_local_path: target path to local file on UE PC
        :param file_ue_path: file path on Android UE
        """
        self.ue_control.adb_pull_file(file_local_path, file_ue_path)

    def transfer_qmdl_from_ue_to_pc(self, windows_logs_dir, mdm=None):
        """
        Transfer qmdl file from Android UE to UE PC
        :param windows_logs_dir: target path to logs directory on Windows UE PC
        :return:
        """
        if mdm is not None:
            try:
                ue_file_path, ue_file_name = self.get_android_qmdl_file_path(self.dir_logs_path + '/' + mdm)
            except DirectoryNotFoundError as dir_not_found_exception:
                self.logger.error("Tried to download {} file from UE, but it's not found. Retrying with {}. Detailed"
                                  " exception:{}".format(self.dir_logs_path + '/' + mdm, self.dir_logs_path,
                                                         dir_not_found_exception))
                ue_file_path, ue_file_name = self.get_android_qmdl_file_path(self.dir_logs_path)
        else:
            ue_file_path, ue_file_name = self.get_android_qmdl_file_path(self.dir_logs_path)
        ue_file_path = ue_file_path.strip()
        ue_pc_file_path = (os.path.join(windows_logs_dir, ue_file_name)).strip()
        self.adb_pull_file(ue_pc_file_path, ue_file_path)
        if os.path.isfile(ue_pc_file_path):
            self.logger.debug("Pulled qmdl file from UE '{ue_path}' to UE PC '{ue_pc_path}'"
                              .format(ue_path=ue_file_path, ue_pc_path=ue_pc_file_path))
            return ue_pc_file_path, ue_file_name
        raise QmdlFileTransferToUePcError('File {} was not properly transferred to UE PC!'.format(ue_file_path))

    def copy_diag_cfg_to_ue(self):
        """Transfer DIAG.cfg file from Windows UE PC to Android UE."""
        if hasattr(self, 'diag_cfg_win_path'):
            self.ensure_file_exists(path=self.diag_cfg_win_path)
            self.adb_push_file(self.diag_cfg_win_path, self.DIAG_CFG_PATH)
        else:
            raise AttributeError('self.diag_cfg_win_path does not exist')

    def ensure_file_exists(self, path):
        """
        Method used to ensure that given file exists on Windows UE PC
        :param path: path to file on Windows UE PC
        """
        if not os.path.isfile(path):
            raise FileWasNotFoundError('File {} does not exist!'.format(path))

    def get_android_qmdl_file_path(self, andr_dir_logs_path):
        """
        Returns path to qmdl file on Android UE
        :param andr_dir_logs_path: Path to directory with logs on Android UE
        :return: path to qmdl file on Android UE
        """
        result = self._run_cmd_on_ue_and_expect_something_in_output('ls {}'.format(andr_dir_logs_path),
                                                                    'No such file or directory')
        if not result:
            raise DirectoryNotFoundError('Can not find directory: {}'.format(andr_dir_logs_path))
        ls_cmd = 'ls {} | grep qmdl'.format(andr_dir_logs_path)
        self.logger.debug('Looking for captured qmdl files using command = {}'.format(ls_cmd))
        out = self._run_cmd_on_ue_and_return_output_lines(ls_cmd)
        if any('Permission denied' in str(line) for line in out) or not out:
            self.logger.error('Permission denied when running {} from app shell or output is empty, '
                              'retrying with adb shell...'.format(ls_cmd))
            out, err = self._run_cmd_in_adb_shell(ls_cmd, get_output=True)
            self.logger.debug('When run {} cmd from adb shell result was:{}, err:{}'.format(ls_cmd, out, err))
        if out:
            if type(out) == list:
                qmdl_filename = out[-1]
            else:
                qmdl_filename = out
            andr_qmdl_path = andr_dir_logs_path + '/' + qmdl_filename
            return andr_qmdl_path, qmdl_filename
        raise QmdlNotFoundOnAndroidError('Qmdl file on Android UE not found! Searched in folder {}. '
                                         '{} command output = {}'.format(andr_dir_logs_path, ls_cmd, out))

    def get_windows_qmdl_file_path(self, win_dir_logs_path):
        """
        Returns path to qmdl file on Windows UE PC
        :param win_dir_logs_path: Path to directory with logs on Windows UE PC
        :return: path to qmdl file on Windows UE PC
        """
        if not os.path.isdir(win_dir_logs_path):
            raise DirectoryNotFoundError('Can not find directory: {}'.format(win_dir_logs_path))
        else:
            files = os.listdir(win_dir_logs_path)
            qmdl_file_path = ''
            for file_in_qmdl_dir in files:
                pathname = os.path.splitext(os.path.join(win_dir_logs_path, file_in_qmdl_dir))
                if pathname[1] == ".qmdl":
                    qmdl_file_path = os.path.join(win_dir_logs_path, file_in_qmdl_dir)
            if qmdl_file_path == '':
                raise QmdlNotFoundOnUePcError('Can not find qmdl file in folder {}'.format(win_dir_logs_path))
            else:
                return qmdl_file_path

    def cleanup_ue(self):
        """Delete all temporary files and folders generated on Android UE during collecting RRC messages."""
        self.logger.debug('Running UE cleanup - deleting tmp folders and files.')
        cmd_ls = 'ls ' + self.LOGS_ROOT_PATH
        cmd_del = 'cd ' + self.LOGS_ROOT_PATH + '; {} rm -rf '.format(self.ue_root_cmd)
        out_ls = self._run_cmd_on_ue_and_return_output_lines(cmd_ls)
        self.logger.debug('Output from {} cmd = {}'.format(cmd_ls, out_ls))
        self._delete_tmp_files_in_android(cmd_del, out_ls)

    def _delete_tmp_files_in_android(self, cmd_del, out_ls):
        for element in out_ls:
            re_out = re.search(u'\\d{8}_\\d{6}', element)
            if re_out:
                cmd_del_element = cmd_del + element
                self.logger.debug('Running command: {}'.format(cmd_del_element))
                self._run_cmd_on_ue_and_return_output_lines(cmd_del_element)
                cmd_ls_el = 'cd ' + self.LOGS_ROOT_PATH + '; ls | grep ' + element
                out_ls2 = self._run_cmd_on_ue_and_return_output_lines(cmd_ls_el)
                self.logger.debug('Output from {} command after cleanup: {}'.format(cmd_ls_el, out_ls2))
                if out_ls2:
                    self.logger.warning('Could not delete file or dir: {}'.format(element))

    def _create_decoded_file_name(self):
        new_file_name = 'qmdl_decoded' + '_' + self._get_current_date_time() + '.txt'
        return new_file_name

    def _get_analyzed_txt_filepaths(self, analyzer_output_dir):
        self.logger.debug('analyzer_output_dir={}'.format(analyzer_output_dir))
        analyzed_txt_filepaths = [os.path.join(analyzer_output_dir, filename) for filename in os.listdir(analyzer_output_dir)]
        self.logger.debug('Files with qcat analysis: {}'.format(analyzed_txt_filepaths))
        if not analyzed_txt_filepaths:
            raise DecodedQmdlFileError(
                'Can not find analysis of decoded qmdl file in directory: {}. Please check qcat analyzer.'.format(analyzer_output_dir))
        return analyzed_txt_filepaths

    def _create_qmdl_decoder(self, qmdl_win_filepath, qcat_analyzer, rrc_filter_file_path=None):
        qmdl_decoder = QmdlDecoder(qmdl_win_filepath, self.qcat_exe_path, qcat_analyzer, rrc_filter_file_path)
        return qmdl_decoder

    def _decode_qmdl(self, windows_logs_dir, qcat_analyzer, rrc_filter_file_path=None, mdm=None):
        qmdl_file_path, ue_file_name = self.transfer_qmdl_from_ue_to_pc(windows_logs_dir, mdm)
        self.logger.debug('TAUE-1275 qmdl_file_path={}'.format(qmdl_file_path))
        qmdl_decoder = self._create_qmdl_decoder(windows_logs_dir, qcat_analyzer, rrc_filter_file_path)
        qmdl_decoder.qmdl_file_path = qmdl_file_path
        qmdl_decoder.decode_qmdl_file()
        decoded_qmdl_filepath = qmdl_file_path.replace('.qmdl', '.txt')
        analyzer_output_file = None
        if qcat_analyzer:
            analyzer_output_file = qmdl_file_path.rstrip('.qmdl') + os.sep
            qmdl_decoder.analyze_qmdl_file(analyzer_output_file)
        self._wait_for_decoded_qmdl_file(decoded_qmdl_filepath)
        return decoded_qmdl_filepath, analyzer_output_file

    def _wait_for_decoded_qmdl_file(self, decoded_filepath, timeout=10):
        end_time = time.time() + float(timeout)
        while not os.path.isfile(decoded_filepath):
            self.logger.debug('Not found decoded file in {} waiting 1s...'.format(decoded_filepath))
            if time.time() > end_time:
                raise DecodedQmdlFileError('Can not find decoded qmdl file {}'.format(decoded_filepath))
            time.sleep(1)

    def _other_preparations_before_run_diag_mdlog(self):
        pass


class DiagUeRunnerQualcomm(DiagUeRunner):
    """DiagUeRunnerQualcomm"""
    PROC_LIST_CMD = {'QUALCOMM MSM8998 for arm64': 'su 0 ps',
                     'QUALCOMM MSM8996 for arm64': 'su 0 ps',
                     'QUALCOMM MSM8947 for arm64': 'su 0 ps',
                     'Unknown MSM8994 for arm64': 'su 0 ps'}

    def __init__(self, ue_control):
        """
        Basic initialization.
        :param ue_control:
        """
        super(DiagUeRunnerQualcomm, self).__init__(ue_control)
        self.adb_runner = AdbCmdRunner()

    def run_diag_mdlog_cmd(self):
        """Start diag_mdlog application on Android UE."""
        diag_mdlog_cmd = self._create_cmd_to_run_diag()
        self.logger.debug("Starting diag_mdlog on adb shell by cmd: " + diag_mdlog_cmd)
        self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['shell'] + diag_mdlog_cmd.split(' '),
                                            wait_for=False)
        # self.logger.debug("Got result from adb shell, out: '{}', err: '{}'".format(_out, _err))

    def _diag_mdlog_kill(self):
        cmd = self._create_cmd_to_run_diag_kill()
        self.logger.debug("Starting diag_mdlog on adb shell by cmd: " + cmd)
        _out, _err = self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['shell'] + cmd.split(' '))
        self.logger.debug("Got result from adb shell, out: '{}', err: '{}'".format(_out, _err))

    def _create_cmd_to_run_diag(self):
        cmd_opt = ''
        if bool(self.qmdl_size):
            cmd_opt = '-s {} -o {}'.format(self.qmdl_size, self.dir_logs_path)
        else:
            cmd_opt = '-o {}'.format(self.dir_logs_path)
        return 'echo $$; diag_mdlog -m /sdcard/diag_logs/DIAG.cfg {} > {}/diag_out.txt'.format(
            cmd_opt, self.LOGS_ROOT_PATH)

    def get_ue_su_prefix(self):
        """
        Make sure this UE is rooted.
        :return:
        """
        self.logger.debug("Run adb root")
        _out, _err = self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['root'])
        self.logger.debug("Got result from adb root, out: '{}', err: '{}'".format(_out, _err))
        return ""

    def _run_cmd_on_ue_and_get_non_blocking_output(self, diag_mdlog_cmd):
        return self.ue_control.ueman.run_cmd_and_get_non_blocking_output(diag_mdlog_cmd, prog_name='sh')

    def _is_diag_mdlog_running(self):
        proc_list_cmd = self._get_proc_list_cmd()
        _out, _err = self.adb_runner.adb_read_adb_output(self.ue_control.sn_number, ['shell'] + proc_list_cmd.split(' '))
        self.logger.debug("Got result from adb shell, out: '{}', err: '{}'".format(_out, _err))
        if 'diag_mdlog' in _out:
            self.logger.debug('diag_mdlog process found!')
            return True
        self.logger.debug('diag_mdlog process not found!')
        return False

    def _get_proc_list_cmd(self):
        try:
            proc_list_cmd = self.PROC_LIST_CMD[self.ue_model]
        except KeyError:
            proc_list_cmd = 'su 0 ps -A'
        return proc_list_cmd

    def _create_cmd_to_run_diag_kill(self):
        return 'diag_mdlog -k'

    def ensure_logs_root_andr_exists(self):
        """Ensures that Android logs directory exists."""
        cmd = 'ls ' + self.LOGS_ROOT_PATH
        cmd_mkdir = 'mkdir ' + self.LOGS_ROOT_PATH
        if not self._run_cmd_on_ue_and_expect_something_in_output(cmd, 'No such file or directory'):
            self.logger.debug('Running cmd using adb: {}'.format(self.LOGS_ROOT_PATH))
            result, err = self._run_cmd_in_adb_shell(cmd_mkdir, get_output=True)
            self.logger.debug('Command {} executed with result {} and err {}'.format(cmd_mkdir, result, err))

    def cleanup_ue(self):
        """Delete all temporary files and folders generated on Android UE during collecting RRC messages."""
        self.logger.debug('Running UE cleanup - deleting tmp folders and files.')
        cmd_ls = 'ls ' + self.LOGS_ROOT_PATH
        out_ls = self._run_cmd_on_ue_and_return_output_lines(cmd_ls)
        self.logger.debug('Output from {} cmd = {}'.format(cmd_ls, out_ls))
        cmd_del = 'cd ' + self.LOGS_ROOT_PATH + ';rm -rf ' + ' '.join(out_ls)
        self.logger.debug("Cleanup UE with command: {}".format(cmd_del))
        out, err = self._run_cmd_in_adb_shell(cmd_del, get_output=True)
        self.logger.debug("Cleanup finished with out {} and err {}".format(out, err))


class DiagUeRunnerFactory(object):
    """DiagUeRunnerFactory"""
    UE_MODELS_SPECIAL_DIAG_UE_RUNNER_CREATORS = {
        "QUALCOMM MSM8998 for arm64": DiagUeRunnerQualcomm,
        "Unknown MSM8996 for arm64": DiagUeRunnerQualcomm,
        "Unknown MSM8994 for arm64": DiagUeRunnerQualcomm,
        "QUALCOMM SDM845 for arm64": DiagUeRunnerQualcomm,
        "QUALCOMM msmnile for arm64": DiagUeRunnerQualcomm,
        "QUALCOMM MSM8996 for arm64": DiagUeRunnerQualcomm,
        "QUALCOMM MSM8994 for arm64": DiagUeRunnerQualcomm,
        "QUALCOMM MSM8947 for arm64": DiagUeRunnerQualcomm
    }

    def create_diag_ue_runner(self, android_control):
        """
        Creates DiagUeRunner for specifed Android UE
        :param android_control:
        :return: DiagUeRunner
        """
        ue_model = android_control.get_cached_ue_model()
        if ue_model in DiagUeRunnerFactory.UE_MODELS_SPECIAL_DIAG_UE_RUNNER_CREATORS or android_control.is_qualcomm_prototype:
            self.UE_MODELS_SPECIAL_DIAG_UE_RUNNER_CREATORS[ue_model] = DiagUeRunnerQualcomm
            return DiagUeRunnerFactory.UE_MODELS_SPECIAL_DIAG_UE_RUNNER_CREATORS[ue_model](android_control)
        return DiagUeRunner(android_control)
